const cfg = $('Config').first().json;
const url = cfg.url || '';
const recipient = cfg.recipientEmail || '';
let host = url;
try { host = url.replace(/^https?:\/\//, '').replace(/\/.*$/, '').replace(/^www\./, '') || url; } catch (e) {}

const mobileResp = $('PageSpeed Mobile').first().json;
const desktopResp = $('PageSpeed Desktop').first().json;

function extract(resp) {
  resp = resp || {};
  const le = (resp.loadingExperience && resp.loadingExperience.metrics) || {};
  const lh = resp.lighthouseResult || {};
  const audits = lh.audits || {};
  const cats = lh.categories || {};
  const perfScore = (cats.performance && typeof cats.performance.score === 'number') ? Math.round(cats.performance.score * 100) : null;
  const fLcp = le.LARGEST_CONTENTFUL_PAINT_MS ? le.LARGEST_CONTENTFUL_PAINT_MS.percentile : null;
  const fInp = le.INTERACTION_TO_NEXT_PAINT ? le.INTERACTION_TO_NEXT_PAINT.percentile : (le.EXPERIMENTAL_INTERACTION_TO_NEXT_PAINT ? le.EXPERIMENTAL_INTERACTION_TO_NEXT_PAINT.percentile : null);
  const fClsRaw = le.CUMULATIVE_LAYOUT_SHIFT_SCORE ? le.CUMULATIVE_LAYOUT_SHIFT_SCORE.percentile : null;
  const fCls = (fClsRaw !== null && fClsRaw !== undefined) ? fClsRaw / 100 : null;
  const labLcp = audits['largest-contentful-paint'] ? audits['largest-contentful-paint'].numericValue : null;
  const labCls = audits['cumulative-layout-shift'] ? audits['cumulative-layout-shift'].numericValue : null;
  const labTbt = audits['total-blocking-time'] ? audits['total-blocking-time'].numericValue : null;
  const hasField = (fLcp !== null && fLcp !== undefined);
  return {
    hasField: hasField,
    lcp: (fLcp !== null && fLcp !== undefined) ? fLcp : labLcp,
    inp: (fInp !== null && fInp !== undefined) ? fInp : null,
    tbt: labTbt,
    cls: (fCls !== null && fCls !== undefined) ? fCls : labCls,
    perfScore: perfScore
  };
}

const m = extract(mobileResp);
const d = extract(desktopResp);

function stLcp(v){ if(v===null||v===undefined) return null; if(v<=2500) return 'good'; if(v<=4000) return 'ni'; return 'poor'; }
function stInp(v){ if(v===null||v===undefined) return null; if(v<=200) return 'good'; if(v<=500) return 'ni'; return 'poor'; }
function stCls(v){ if(v===null||v===undefined) return null; if(v<=0.1) return 'good'; if(v<=0.25) return 'ni'; return 'poor'; }
function stScore(v){ if(v===null||v===undefined) return null; if(v>=90) return 'good'; if(v>=50) return 'ni'; return 'poor'; }

const META = {
  good: { color: '#16a34a', bg: '#dcfce7', label: 'Good', dot: '🟢' },
  ni:   { color: '#b45309', bg: '#fef3c7', label: 'Needs work', dot: '🟡' },
  poor: { color: '#dc2626', bg: '#fee2e2', label: 'Poor', dot: '🔴' },
  none: { color: '#6b7280', bg: '#f3f4f6', label: 'No data', dot: '⚪' }
};

function fmtLcp(v){ return (v===null||v===undefined) ? '—' : (v/1000).toFixed(2) + ' s'; }
function fmtInp(v){ return (v===null||v===undefined) ? '—' : Math.round(v) + ' ms'; }
function fmtCls(v){ return (v===null||v===undefined) ? '—' : v.toFixed(3); }
function fmtScore(v){ return (v===null||v===undefined) ? '—' : String(v); }

function cell(valueStr, status){
  const meta = META[status || 'none'];
  return '<td style="padding:10px 14px;text-align:center;border-bottom:1px solid #e5e7eb;">' +
    '<span style="display:inline-block;padding:4px 10px;border-radius:9999px;background:' + meta.bg + ';color:' + meta.color + ';font-weight:600;font-size:13px;">' +
    meta.dot + ' ' + valueStr + '</span></td>';
}

function tr(metric, target, mVal, mSt, dVal, dSt){
  return '<tr>' +
    '<td style="padding:10px 14px;border-bottom:1px solid #e5e7eb;font-weight:600;color:#111827;">' + metric +
    '<div style="font-weight:400;color:#6b7280;font-size:12px;">' + target + '</div></td>' +
    cell(mVal, mSt) + cell(dVal, dSt) + '</tr>';
}

const statuses = [stLcp(m.lcp),stInp(m.inp),stCls(m.cls),stScore(m.perfScore),stLcp(d.lcp),stInp(d.inp),stCls(d.cls),stScore(d.perfScore)];
let overall = 'good';
for (let i=0;i<statuses.length;i++){ const s=statuses[i]; if(s==='poor'){ overall='poor'; break; } if(s==='ni' && overall!=='poor'){ overall='ni'; } }
const overallDot = META[overall].dot;
const dateStr = $now.toFormat('dd LLL yyyy');

const rowsHtml =
  tr('Largest Contentful Paint (LCP)','Good ≤ 2.5s', fmtLcp(m.lcp), stLcp(m.lcp), fmtLcp(d.lcp), stLcp(d.lcp)) +
  tr('Interaction to Next Paint (INP)','Good ≤ 200ms', fmtInp(m.inp), stInp(m.inp), fmtInp(d.inp), stInp(d.inp)) +
  tr('Cumulative Layout Shift (CLS)','Good ≤ 0.1', fmtCls(m.cls), stCls(m.cls), fmtCls(d.cls), stCls(d.cls)) +
  tr('Performance Score','Good ≥ 90', fmtScore(m.perfScore), stScore(m.perfScore), fmtScore(d.perfScore), stScore(d.perfScore));

const fieldNote = (!m.hasField && !d.hasField)
  ? '<p style="color:#6b7280;font-size:12px;margin:8px 0 0;">No real-user (CrUX) field data was available for this URL, so lab metrics are shown. INP is a field-only metric and shows as a dash for lab data.</p>'
  : '<p style="color:#6b7280;font-size:12px;margin:8px 0 0;">Values reflect real-user (CrUX) field data where available, otherwise Lighthouse lab data.</p>';

const html =
'<div style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:640px;margin:0 auto;color:#111827;">' +
  '<h2 style="margin:0 0 4px;">' + overallDot + ' Core Web Vitals — ' + host + '</h2>' +
  '<p style="margin:0 0 16px;color:#6b7280;font-size:14px;">Daily report · ' + dateStr + '</p>' +
  '<table style="width:100%;border-collapse:collapse;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;font-size:14px;">' +
    '<thead><tr style="background:#f9fafb;">' +
      '<th style="padding:10px 14px;text-align:left;border-bottom:1px solid #e5e7eb;">Metric</th>' +
      '<th style="padding:10px 14px;text-align:center;border-bottom:1px solid #e5e7eb;">📱 Mobile</th>' +
      '<th style="padding:10px 14px;text-align:center;border-bottom:1px solid #e5e7eb;">💻 Desktop</th>' +
    '</tr></thead><tbody>' + rowsHtml + '</tbody></table>' +
  fieldNote +
  '<p style="margin:16px 0 0;"><a href="https://pagespeed.web.dev/analysis?url=' + encodeURIComponent(url) + '" style="color:#2563eb;">View full PageSpeed report</a></p>' +
'</div>';

const subject = overallDot + ' Core Web Vitals — ' + host + ' — Mobile ' + fmtScore(m.perfScore) + '/100, Desktop ' + fmtScore(d.perfScore) + '/100';

return [{ json: { subject: subject, html: html, recipient: recipient, host: host, mobile: m, desktop: d } }];
